&lt;div&gt;
  &lt;div class="my-controls"&gt;
    &lt;button id="step-btn"&gt;Step&lt;/button&gt;
    &lt;button id="reset-btn"&gt;Reset&lt;/button&gt;
    &lt;select id="mode-sel"&gt;
      &lt;option value="a"&gt;Mode A&lt;/option&gt;
      &lt;option value="b"&gt;Mode B&lt;/option&gt;
    &lt;/select&gt;
