      const wSum = wA + wB + wC;
      mx = (wA*A[0] + wB*B[0] + wC*C[0]) / wSum;
      my = (wA*A[1] + wB*B[1] + wC*C[1]) / wSum;
    }
    return [mx, my];
  }

